"""Create an invoice total from product line items and an order coupon."""

from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def _to_decimal(value, message):
    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError):
        raise ValueError(message)


def invoice_total(items, coupon="0"):
    amount = Decimal("0")
    for item in items:
        price = _to_decimal(item["unit_price"], "invalid product line")
        count = item["quantity"]
        if not price.is_finite() or price < 0 or not isinstance(count, int) or count < 1:
            raise ValueError("invalid product line")
        amount += price * count
    discount = _to_decimal(coupon, "invalid coupon")
    if not discount.is_finite() or discount < 0:
        raise ValueError("invalid coupon")
    amount = max(Decimal("0"), amount - discount)
    total = amount.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    return {"total": format(total, ".2f"), "currency": "CNY", "lines": len(items)}

