"""Publish a student's weighted mark and scholarship eligibility."""

from decimal import Decimal, InvalidOperation, ROUND_HALF_UP, localcontext

_ONE_DECIMAL = Decimal("0.1")
_MIN_SCORE = Decimal("0")
_MAX_SCORE = Decimal("100")


def _to_decimal(value):
    """Convert a decimal string input to an exact :class:`Decimal`."""
    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError):
        raise ValueError("invalid assessment")


def publish_grade(assessments):
    points = Decimal("0")
    weight_sum = Decimal("0")
    for assessment in assessments:
        score = _to_decimal(assessment["score"])
        weight = _to_decimal(assessment["weight"])
        if not _MIN_SCORE <= score <= _MAX_SCORE or weight <= 0:
            raise ValueError("invalid assessment")
        points += score * weight
        weight_sum += weight
    if weight_sum == 0:
        raise ValueError("no assessments")
    with localcontext() as ctx:
        ctx.prec = 60
        average = (points / weight_sum).quantize(_ONE_DECIMAL, rounding=ROUND_HALF_UP)
    return {
        "mark": format(average, ".1f"),
        "passed": average >= 60,
        "scholarship": average >= 85,
    }

